  const getInventory=storeCode=>inventoryRows().find(x=>(x.storeCode||"")===(storeCode||""))||{storeCode:storeCode||"",rawChicken:0,cookedChicken:0,mushrooms:0,hatiAmpela:0,friedBakso:0,ceker:0};
  const setInventory=(storeCode,patch)=>{const rows=inventoryRows(),i=rows.findIndex(x=>(x.storeCode||"")===(storeCode||"")),next={...(i>=0?rows[i]:getInventory(storeCode)),...patch,storeCode:storeCode||"",updatedAt:new Date().toISOString()};if(i>=0)rows[i]=next;else rows.unshift(next);localStorage.setItem(INVENTORY_KEY,JSON.stringify(rows));return next;};
  const inventoryCategory=name=>{const n=String(name||"").toLowerCase().normalize("NFD").replace(/[\\u0300-\\u036f]/g,"");if(n.includes("mentah"))return n.includes("ayam")?"rawChicken":null;if(n.includes("ayam")&&(n.includes("goreng")||n.includes("original")||n.includes("spicy")||n.includes("geprek")||n.includes("matang")))return "cookedChicken";if(n.includes("jamur"))return "mushrooms";if(n.includes("hati")||n.includes("ampela")||n.includes("rampela"))return "hatiAmpela";if(n.includes("bakso"))return "friedBakso";if(n.includes("ceker"))return "ceker";return null;};
  const DAMAGE_KEY="dashboardowner_damaged_stock_v1";let ownerInventoryTab="stock";
