  const saleTimestamp=x=>{const t=Date.parse(x?.createdAt||"");if(Number.isFinite(t))return new Date(t);const d=new Date(String(x?.date||"")+"T12:00:00");return Number.isFinite(d.getTime())?d:new Date();};
