    const damages=read(DAMAGE_KEY,[]).filter(x=>(!store||x.storeCode===store)&&x.date===today),totals={};damages.forEach(x=>totals[x.itemKey]=(totals[x.itemKey]||0)+Number(x.quantity||0));
    const tabs='<div class="owner-inventory-tabs" role="tablist" aria-label="Data stok"><button type="button" role="tab" aria-selected="'+(ownerInventoryTab==="stock")+'" data-inventory-tab="stock" class="'+(ownerInventoryTab==="stock"?"active":"")+'">Stok Bahan &amp; Makanan</button><button type="button" role="tab" aria-selected="'+(ownerInventoryTab==="sold")+'" data-inventory-tab="sold" class="'+(ownerInventoryTab==="sold"?"active":"")+'">Terjual</button><button type="button" role="tab" aria-selected="'+(ownerInventoryTab==="damage")+'" data-inventory-tab="damage" class="'+(ownerInventoryTab==="damage"?"active":"")+'">Rusak</button></div><p class="owner-inventory-date">Data hari ini · '+escapeHtml(new Date().toLocaleDateString("id-ID",{day:"numeric",month:"long",year:"numeric"}))+'</p>';
    let body="";
    if(ownerInventoryTab==="stock"){body='<div class="owner-inventory-grid">'+INVENTORY_ITEMS.map(i=>{const q=Math.max(0,Math.floor(Number(stock[i.key])||0)),c=2*Math.PI*31,p=q?Math.min(c,12+Math.log10(q+1)*18):0;return '<div class="owner-inventory-item"><div class="owner-stock-ring" style="--stock-color:'+i.color+'"><svg viewBox="0 0 76 76"><circle class="owner-stock-track" cx="38" cy="38" r="31"></circle><circle class="owner-stock-progress" cx="38" cy="38" r="31" style="stroke-dasharray:'+p+' '+c+'"></circle></svg><strong>'+q+'</strong></div><b>'+escapeHtml(i.label)+'</b><small>'+i.unit+'</small></div>';}).join("")+'</div>';}
