    document.getElementById("analysis-online").onclick=()=>renderSalesPage("online");
    document.querySelectorAll("[data-chart-source]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-chart-source]").forEach(x=>x.classList.toggle("active",x===b));renderAnalysisChart(b.dataset.chartSource);});
    document.querySelector('[data-chart-source="offline"]').classList.add("active");
